// Some portions generated by Claude

import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.regex.Pattern;

import org.apache.jena.graph.Node;
import org.apache.jena.query.Query;
import org.apache.jena.query.QueryExecution;
import org.apache.jena.query.QueryFactory;
import org.apache.jena.query.QuerySolution;
import org.apache.jena.query.ResultSet;
import org.apache.jena.query.Syntax;
import org.apache.jena.rdf.model.RDFNode;
import org.apache.jena.riot.Lang;
import org.apache.jena.riot.RDFParser;
import org.apache.jena.sparql.core.DatasetGraph;
import org.apache.jena.sparql.core.DatasetGraphFactory;
import org.apache.jena.sparql.core.Quad;
import org.apache.jena.update.UpdateAction;

/**
 * Jena ARQ oracle for the WP9 differential corpus. Emulates RDF4J's no-dataset semantics: the default graph is the
 * union of all graphs, GRAPH ranges over named graphs only. Phases: pre (loaded data), post (after the case update).
 */
public class JenaRunner {

	public static void main(String[] args) throws Exception {
		List<String> lines = Files.readAllLines(Path.of(args[0]), StandardCharsets.UTF_8);
		Pattern filter = args.length > 2 ? Pattern.compile(args[2]) : null;
		try (PrintWriter out = new PrintWriter(Files.newBufferedWriter(Path.of(args[1]), StandardCharsets.UTF_8))) {
			String id = null, section = null, qflags = "";
			int qidx = -1;
			StringBuilder cur = new StringBuilder(), data = null;
			List<String[]> qs = new ArrayList<>();
			String upd = null;
			for (String line : lines) {
				if (line.startsWith("### ")) {
					if ("QUERY".equals(section)) {
						qs.add(new String[] { String.valueOf(qidx), cur.toString() });
					} else if ("UPDATE".equals(section)) {
						upd = cur.toString();
					}
					String[] p = line.substring(4).split(" ", 3);
					section = p[0];
					cur = new StringBuilder();
					switch (section) {
					case "CASE" -> {
						id = p[1];
						qs = new ArrayList<>();
					}
					case "DATA" -> data = cur;
					case "QUERY" -> qidx = Integer.parseInt(p[1]);
					case "END" -> {
						if (filter == null || filter.matcher(id).find()) {
							runCase(out, id, data.toString(), qs, upd);
						}
					}
					default -> {
					}
					}
					continue;
				}
				cur.append(line).append('\n');
			}
		}
	}

	static void runCase(PrintWriter out, String id, String data, List<String[]> qs, String upd) {
		DatasetGraph base = DatasetGraphFactory.createTxnMem();
		RDFParser.fromString(data, Lang.TRIG).base("http://ex.org/").parse(base);
		for (String[] q : qs) {
			out.println(id + "\t" + q[0] + "\tjena\tpre\t" + run(union(base), q[1]));
		}
		String u = "OK";
		try {
			UpdateAction.parseExecute(upd, base);
		} catch (Throwable t) {
			u = "UPDATE-ERROR " + t.getClass().getSimpleName();
		}
		out.println(id + "\t-\tjena\tupdate\t" + u);
		for (String[] q : qs) {
			out.println(id + "\t" + q[0] + "\tjena\tpost\t" + run(union(base), q[1]));
		}
		out.flush();
	}

	static DatasetGraph union(DatasetGraph base) {
		DatasetGraph v = DatasetGraphFactory.createTxnMem();
		Iterator<Quad> it = base.find();
		while (it.hasNext()) {
			Quad q = it.next();
			v.add(q);
			if (!q.isDefaultGraph()) {
				v.getDefaultGraph().add(q.asTriple());
			}
		}
		return v;
	}

	static String run(DatasetGraph ds, String text) {
		try {
			Query query = QueryFactory.create(text, Syntax.syntaxARQ);
			try (QueryExecution qe = QueryExecution.dataset(org.apache.jena.query.DatasetFactory.wrap(ds)).query(query).timeout(30000).build()) {
				if (query.isAskType()) {
					return "BOOL " + qe.execAsk();
				}
				if (query.isSelectType()) {
					ResultSet rs = qe.execSelect();
					List<String> names = new ArrayList<>(rs.getResultVars());
					List<String> rows = new ArrayList<>();
					while (rs.hasNext()) {
						QuerySolution s = rs.next();
						List<String> cells = new ArrayList<>();
						for (String n : names) {
							RDFNode v = s.get(n);
							if (v != null) {
								cells.add(n + "=" + value(v.asNode()));
							}
						}
						Collections.sort(cells);
						rows.add(String.join(" | ", cells));
					}
					Collections.sort(rows);
					Collections.sort(names);
					return "ROWS " + rows.size() + " " + names + " :: " + String.join(" ;; ", rows);
				}
				return "ERROR unsupported";
			}
		} catch (Throwable t) {
			return "ERROR " + t.getClass().getSimpleName() + "\t" + String.valueOf(t.getMessage()).replace('\n', ' ')
					.replace('\t', ' ');
		}
	}

	static String value(Node n) {
		if (n.isBlank()) {
			return "_:b";
		}
		if (n.isURI()) {
			return "<" + n.getURI() + ">";
		}
		if (n.isLiteral()) {
			String lex = n.getLiteralLexicalForm().replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")
					.replace("\r", "\\r");
			String lang = n.getLiteralLanguage();
			if (lang != null && !lang.isEmpty()) {
				return "\"" + lex + "\"@" + lang;
			}
			String dt = n.getLiteralDatatypeURI();
			if (dt == null || dt.equals("http://www.w3.org/2001/XMLSchema#string")) {
				return "\"" + lex + "\"";
			}
			return "\"" + lex + "\"^^<" + dt + ">";
		}
		return n.toString();
	}
}
